  ('us-l1a', 1, '{"schemaVersion":1,"routeId":"us-l1a","number":1,"title":"L-1A intracompany transferee: manager or executive, including one sent to open a new U.S. office (temporary)","country":"US","tags":["work","temporary-residence"],"effectiveFrom":"2024-04-01","status":"open","currency":"USD","sources":[{"id":"usc-1101-l","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapI-sec1101.htm","title":"8 U.S.C. 1101(a)(15)(L): one continuous year of employment abroad in the 3 years before, to continue for the same employer or its affiliate or subsidiary; the spouse and minor children","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1101-capacity","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapI-sec1101.htm","title":"8 U.S.C. 1101(a)(44)(A) and (B): managerial capacity and executive capacity, each an assignment within an organization in which the employee primarily manages or directs","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1101","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapI-sec1101.htm","title":"8 U.S.C. 1101(b)(1): a child is an unmarried person under twenty-one, including a stepchild, an adopted child, a legitimated child and one born out of wedlock with a bona fide tie to the father","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1101-spouse","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapI-sec1101.htm","title":"8 U.S.C. 1101(a)(35): spouse does not include one by a marriage ceremony where the parties are not physically present in the presence of each other, unless the marriage has been consummated","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1184-l","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapII-partII-sec1184.htm","title":"8 U.S.C. 1184(c)(2)(D)(i): an L-1