  ('us-eb1c', 1, '{"schemaVersion":1,"routeId":"us-eb1c","number":1,"title":"EB-1C multinational manager or executive: employer petition, no labor certification (permanent residence)","country":"US","tags":["work","permanent-residence"],"effectiveFrom":"2024-04-01","status":"open","currency":"USD","sources":[{"id":"usc-1153-eb1c","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapII-partI-sec1153.htm","title":"8 U.S.C. 1153(b)(1)(C) Certain multinational executives and managers: 1 year of employment in the 3 years before, to continue for the same employer or its affiliate or subsidiary","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1101-capacity","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapI-sec1101.htm","title":"8 U.S.C. 1101(a)(44)(A) and (B): managerial capacity and executive capacity, each an assignment within an organization in which the employee primarily manages or directs","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1153","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapII-partI-sec1153.htm","title":"8 U.S.C. 1153(d): a spouse or child as 8 U.S.C. 1101(b)(1)(A) to (E) defines gets the same status and order of consideration if accompanying or following to join","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1153-child-age","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapII-partI-sec1153.htm","title":"8 U.S.C. 1153(h)(1): a child''s age is that on the date a visa number becomes available, if residence is sought within one year, reduced by the days the petition was pending","kind":"official","verifiedAt":"2026-11-25"},{"id":"usc-1101","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title8/html/USCODE-2024-title8-chap12-subchapI-sec1101.htm","title":"8 U.S.C. 1101(b)(1): a child is an unmarried person under twenty-one, i